/**
 * Trial: LTX 2.5 videos generated by ComfyUI (the LongForge LTX2.5 nodes) instead of the
 * built-in engine.
 *
 * Atelier keeps everything it does today (the model's proposal, the confirmation window, the
 * formats, the roles of the inputs, the gallery): only the job that the built-in worker would
 * run is turned into a ComfyUI graph and sent to a ComfyUI already running on this machine.
 * Switched on by `data/comfy-engine.json` (`{ "enabled": true, "baseUrl": "http://127.0.0.1:7821" }`),
 * read at every generation; without that file nothing changes.
 */
import { randomUUID } from 'node:crypto';
import { readFile, rename, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { ComfyClient, normalizeComfyUrl } from './comfy-client.mjs';

const problem = (message, status = 502) => Object.assign(new Error(message), { status });
// The folder of ComfyUI's input directory where LongForge looks for scene images.
const INPUT_FOLDER = 'longforge_ltx25';
const OUTPUT_NODE = 'render';
// A job names its files by their path on this machine, ComfyUI by their name in its own folders.
const leaf = path => String(path).split(/[\\/]/).pop();
const slashes = path => String(path).replaceAll('\\', '/').toLowerCase();

/** The trial's settings, or null when it is off (no file, disabled, unreadable). */
export async function comfyEngine(dataDir) {
  let stored;
  try {
    stored = JSON.parse(await readFile(join(dataDir, 'comfy-engine.json'), 'utf8'));
  } catch {
    return null;
  }
  if (stored?.enabled !== true) return null;
  try {
    return { baseUrl: normalizeComfyUrl(stored.baseUrl) };
  } catch {
    return null;
  }
}

/**
 * Why this job stays on the built-in engine, or '' when ComfyUI can take it: LongForge is driven
 * here for one new clip (text, start and end images, subject references), not for continuations.
 */
export function comfyUnsupported(job) {
  if (job?.pipeline !== 'ltx25') return 'not an LTX 2.5 job';
  const p = job.parameters;
  if (job.references.some(ref => ref.role === 'source_video')) return 'continuations stay on the built-in engine';
  if (job.references.filter(ref => ref.role === 'msr_image').length > 2) return 'more than two subject references';
  if (p.audio === false) return 'LongForge always renders the sound';
  if (p.fps !== 24) return 'LongForge renders at 24 frames per second';
  if (p.frames < 25 || (p.frames - 1) % 8) return 'clips shorter than one second';
  return '';
}

// Where each file of a job is chosen in the graph: [node, input].
const CHOICES = {
  model: ['UNETLoader', 'unet_name'],
  textEncoder: ['CLIPLoader', 'clip_name'],
  vae: ['VAELoader', 'vae_name'],
  audioVae: ['VAELoader', 'vae_name'],
  lora: ['LongForgeLTXMSRReferences', 'lora_name'],
};

/**
 * The job's model files under the names this ComfyUI gives them. Refuses, before the chat
 * model is unloaded, a ComfyUI without the LongForge nodes or without one of the files.
 */
export async function comfyNames(client, job, { signal } = {}) {
  const nodes = {};
  for (const node of new Set(['LongForgeLTXRender', ...Object.values(CHOICES).map(([name]) => name)])) {
    nodes[node] = (await client.objectInfo({ signal, node }))?.[node];
    if (!nodes[node]) throw problem(`Ce ComfyUI n’a pas le nœud ${node} (LongForge LTX2.5 est-il installé ?).`, 409);
  }
  const paths = { ...job.components, ...(job.loras[0] ? { lora: job.loras[0].path } : {}) };
  const names = {};
  for (const [role, [node, input]] of Object.entries(CHOICES)) {
    if (!paths[role]) continue;
    const spec = nodes[node].input?.required?.[input] ?? nodes[node].input?.optional?.[input] ?? [],
      listed = (Array.isArray(spec[0]) ? spec[0] : spec[1]?.options) ?? [],
      wanted = slashes(paths[role]);
    // A file listed in a sub-folder may have a namesake: the longest entry that ends this path,
    // else (ComfyUI reading another copy of the folder) the same file name.
    names[role] =
      listed.filter(name => wanted.endsWith('/' + slashes(name))).sort((a, b) => b.length - a.length)[0] ??
      listed.find(name => slashes(leaf(name)) === slashes(leaf(paths[role])));
    if (!names[role]) throw problem(`ComfyUI ne liste pas le fichier ${leaf(paths[role])}.`, 409);
  }
  return names;
}

/**
 * The LongForge graph (ComfyUI API format) of one job. `files` maps each reference input to
 * its name in ComfyUI's input folder, `names` the model files to theirs (see comfyNames).
 */
export function longforgeGraph(job, files = {}, names = {}) {
  const p = job.parameters,
    file = input => {
      if (!files[input]) throw problem(`Image ${input} non transmise à ComfyUI.`);
      return files[input];
    },
    named = (key, path) => names[key] ?? leaf(path),
    role = name => job.references.filter(ref => ref.role === name);
  const media = {};
  for (const [key, name] of [
    ['start', 'start_image'],
    ['end', 'end_image'],
  ])
    for (const ref of role(name).slice(0, 1))
      Object.assign(media, { [key + '_file']: file(ref.input), [key + '_enabled']: true });
  const graph = {
    project: {
      class_type: 'LongForgeLTXProject',
      inputs: {
        // One project per generation: LongForge appends scenes to a project, Atelier wants one clip.
        project_name: 'atelier_' + job.id.replaceAll('-', ''),
        action: 'GENERATE NEXT',
        run_mode: 'ONE SCENE',
        scene_data: JSON.stringify([
          { name: 'Scene 1', prompt: p.prompt, ...(Object.keys(media).length ? { ltx: media } : {}) },
        ]),
        selected_scene: 1,
        run_stamp: Math.floor(Math.random() * 2 ** 31),
        export_when_done: true,
      },
    },
    video: {
      class_type: 'LongForgeLTXVideoSettings',
      inputs: {
        width: p.width,
        height: p.height,
        new_seconds: (p.frames - 1) / p.fps,
        overlap_frames: '9',
        audio_continuity: false,
      },
    },
    sampling: {
      class_type: 'LongForgeLTXSampling',
      inputs: {
        seed: p.seed,
        increment_seed: false,
        prompt_enhance: false,
        negative: 'blurry, low quality, distorted, flickering, artifacts',
        sigmas: '1.0, 0.99375, 0.9875, 0.98125, 0.975, 0.909375, 0.725, 0.421875, 0.0',
        video_cfg: 1,
        audio_cfg: 1,
        start_strength: p.start_strength ?? 0.7,
        end_strength: p.end_strength ?? 0.7,
        image_compression: p.image_compression ?? 18,
        eta: 0,
        s_noise: 1,
      },
    },
    model: {
      class_type: 'UNETLoader',
      inputs: { unet_name: named('model', job.components.model), weight_dtype: 'default' },
    },
    clip: {
      class_type: 'CLIPLoader',
      inputs: { clip_name: named('textEncoder', job.components.textEncoder), type: 'ltxv', device: 'default' },
    },
    videoVae: { class_type: 'VAELoader', inputs: { vae_name: named('vae', job.components.vae) } },
    audioVae: { class_type: 'VAELoader', inputs: { vae_name: named('audioVae', job.components.audioVae) } },
    export: {
      class_type: 'LongForgeLTXExportSettings',
      inputs: {
        container: 'MP4',
        codec: 'H264',
        encoder: 'CPU',
        bit_depth: '8',
        interpolation_factor: 1,
        browser_preview: true,
        loop_mode: 'OFF',
        loop_seconds: 1,
        loop_audio: 'CROSSFADE',
        color_drift: 'OFF',
        color_strength: 0.5,
        color_reference_scene: 1,
      },
    },
    [OUTPUT_NODE]: {
      class_type: 'LongForgeLTXRender',
      inputs: {
        job: ['project', 0],
        video_settings: ['video', 0],
        sampling: ['sampling', 0],
        model: ['model', 0],
        clip: ['clip', 0],
        video_vae: ['videoVae', 0],
        audio_vae: ['audioVae', 0],
        export_settings: ['export', 0],
        // The exported film is the result: no second decode for LongForge's own preview panel.
        preview_new_scene: false,
        export_crf: 18,
        repair_audio_seams: true,
        repair_video_seams: false,
        fade_film_edges: true,
        encoding_speed: 'medium',
        metadata_mode: 'NONE',
        diagnostic_wavs: false,
        seam_request: '{}',
      },
    },
  };
  const subjects = role('msr_image');
  if (subjects.length) {
    const lora = job.loras[0];
    if (!lora) throw problem('Les références de sujet demandent leur LoRA.');
    subjects.forEach((ref, index) => {
      graph['subject' + (index + 1)] = { class_type: 'LongForgeLTXOptionalImage', inputs: { image: file(ref.input) } };
    });
    graph.subjects = {
      class_type: 'LongForgeLTXMSRReferences',
      inputs: {
        lora_name: named('lora', lora.path),
        strength_model: lora.strength,
        strength: p.msr_strength ?? 1,
        reference_frames: String(p.msr_frames ?? 33),
        ...Object.fromEntries(subjects.map((_, index) => ['reference' + (index + 1), ['subject' + (index + 1), 0]])),
      },
    };
    graph[OUTPUT_NODE].inputs.media = ['subjects', 0];
  }
  return graph;
}

const IMAGE_TYPES = { '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp' };

/**
 * The ComfyUI that takes this job, checked and ready, or null when the job stays on the
 * built-in engine (trial off, or a job LongForge is not driven for here).
 */
export async function comfyRoute(dataDir, job, { signal, connect = baseUrl => new ComfyClient(baseUrl) } = {}) {
  const engine = await comfyEngine(dataDir);
  if (!engine || comfyUnsupported(job)) return null;
  const client = connect(engine.baseUrl);
  try {
    await client.status({ signal });
  } catch (error) {
    throw problem(`ComfyUI ne répond pas à ${engine.baseUrl} (${error.message}).`, 503);
  }
  return { client, names: await comfyNames(client, job, { signal }), baseUrl: engine.baseUrl };
}

/**
 * Runs one LTX job on ComfyUI and saves its video in Atelier's output folder, with the same
 * result as the built-in worker: `{ jobId, outputs: [{ filename, subfolder, type, width, height }], metadata }`.
 */
export async function runOnComfy(job, { client, names, baseUrl, outputDir, signal, onProgress } = {}) {
  const started = Date.now();
  onProgress?.({ stage: 'sending to ComfyUI' });
  const files = {},
    sent = new Map();
  for (const ref of job.references) {
    const extension = (/\.[a-z0-9]+$/i.exec(ref.path)?.[0] || '').toLowerCase(),
      mime = IMAGE_TYPES[extension];
    if (!mime) throw problem('ComfyUI ne reçoit ici que des images PNG, JPEG ou WebP.');
    if (!sent.has(ref.path)) {
      const stored = await client.upload(await readFile(ref.path), {
        filename: `atelier_${randomUUID().replaceAll('-', '')}${extension}`,
        mime,
        subfolder: INPUT_FOLDER,
        signal,
      });
      sent.set(ref.path, [stored.subfolder, stored.filename].filter(Boolean).join('/'));
    }
    files[ref.input] = sent.get(ref.path);
  }
  const graph = longforgeGraph(job, files, names);
  onProgress?.({ stage: 'sampling video' });
  // ComfyUI counts the steps of the sampler first; what it counts afterwards is the decoding.
  let sampled = false;
  const { promptId, outputs } = await client.run(graph, {
    signal,
    outputNodes: [OUTPUT_NODE],
    mediaType: 'video',
    onProgress: event => {
      if (event.state !== 'step') return;
      if (!sampled && event.value < event.max)
        return onProgress?.({ stage: 'generating video', step: event.value, total: event.max });
      sampled = true;
      onProgress?.({ stage: 'decoding video' });
    },
  });
  onProgress?.({ stage: 'audio decoded' });
  const film = await client.original(outputs[0], { signal });
  const name = randomUUID().replaceAll('-', ''),
    p = job.parameters;
  const result = {
    jobId: job.id,
    outputs: [{ filename: name + '.mp4', subfolder: '', type: 'output', width: p.width, height: p.height }],
    metadata: {
      job,
      parameters: p,
      seconds: Math.round((Date.now() - started) / 10) / 100,
      backend: 'comfyui-longforge',
      frames: p.frames,
      fps: p.fps,
      stage: p.stage,
      audio: true,
      comfy: { baseUrl, promptId, output: outputs[0] },
    },
  };
  // Written under a temporary name first: the gallery never sees half a video.
  await writeFile(join(outputDir, name + '.mp4.tmp'), film.bytes, { flag: 'wx', mode: 0o600 });
  await rename(join(outputDir, name + '.mp4.tmp'), join(outputDir, name + '.mp4'));
  await writeFile(join(outputDir, name + '.json'), JSON.stringify(result), { flag: 'wx', mode: 0o600 });
  return result;
}
